insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_109_v1'
from (values
('127.773.d.1.A',3,'A law clerk is asked to find out whether a tenant can be evicted without notice. Before opening any database, she lists the legal issue, the key terms to search and the jurisdiction. She is:','["planning a legal research strategy", "selecting a jury", "drafting a closing argument", "filing a complaint"]'::jsonb,0,'Good research starts with a plan.','original'),
('127.773.d.1.A',4,'Which step belongs near the beginning of a legal research plan?','["citing every case ever decided", "identifying the legal issue and the controlling jurisdiction", "scheduling the oral argument", "printing the final brief"]'::jsonb,1,'Issue and jurisdiction guide the search.','original'),
('127.773.d.1.B',3,'A paralegal checks a bound reporter in the law library and then runs the same search in an online database to compare results. She is accessing:','["only newspaper ads", "only personal diaries", "print and online sources to find and analyze case law", "only social media posts"]'::jsonb,2,'Case law appears in print and online.','original'),
('127.773.d.1.B',4,'A published court opinion is usually found in a:','["thesaurus", "cookbook", "atlas", "case reporter or legal database"]'::jsonb,3,'Reporters collect opinions.','original'),
('127.773.d.1.C',3,'A Texas trial court must follow a ruling of the Texas Supreme Court, but may only consider a similar ruling from a court in Oregon. The Oregon ruling is:','["persuasive authority", "a statute", "binding precedent", "mandatory authority"]'::jsonb,0,'Other-jurisdiction cases persuade but do not bind.','original'),
('127.773.d.1.C',4,'Authority that a court must follow because it comes from a higher court in the same jurisdiction is called:','["secondary dictum", "mandatory authority", "persuasive authority", "an advisory memo"]'::jsonb,1,'Binding vs. persuasive.','original'),
('127.773.d.1.D',3,'An intern searches a subscription legal database by keyword and filters results by court and date to locate controlling cases. She is researching:','["flight prices with a website", "sports scores with an app", "mandatory and persuasive case history using online databases", "recipes with a search engine"]'::jsonb,2,'Databases such as Lexis or Westlaw filter case law.','original'),
('127.773.d.1.D',4,'Filtering search results by jurisdiction helps a researcher mainly to:','["shorten the font size", "avoid reading opinions", "hide older cases only", "find cases that actually bind the court"]'::jsonb,3,'Jurisdiction filtering targets binding law.','original'),
('127.773.d.1.E',3,'Before relying on an old case in a brief, an attorney runs a citator check to see whether later courts overruled or criticized it. She is:','["shepardizing the case", "translating the case", "indexing the case", "printing the case"]'::jsonb,0,'Citators confirm a case is still good law.','original'),
('127.773.d.1.E',4,'The main reason to shepardize a case is to confirm that it is:','["written clearly", "still good law", "short enough", "recent enough to be new"]'::jsonb,1,'Subsequent history matters.','original'),
('127.773.d.1.F',3,'A student reading a classmate''s memo notices that one quoted case was later reversed and another citation has no page number. She is critiquing:','["a recipe for spice", "a poem for rhyme", "legal writing for accurate cited authority", "a map for scale"]'::jsonb,2,'Check that authority is accurate and complete.','original'),
('127.773.d.1.F',4,'When critiquing a legal memo, a reviewer should confirm that each cited case actually:','["was decided this year", "has a catchy name", "is under ten pages", "supports the point it is cited for"]'::jsonb,3,'Citations must support the proposition.','original'),
('127.773.d.1.G',3,'A student formats a case citation with the party names, volume, reporter, page and year in the order a style manual requires. She is applying:','["Bluebook citation rules", "sports scoring rules", "MLA bibliography rules", "recipe card rules"]'::jsonb,0,'The Bluebook sets legal citation format.','original'),
('127.773.d.1.G',4,'Which tool is the standard guide for how lawyers format citations in briefs?','["a thesaurus", "the Bluebook", "a field guide", "an almanac"]'::jsonb,1,'Bluebook = legal citation format.','original'),
('127.773.d.2.A',3,'A student reads a court opinion and writes down who sued whom, the facts, the question the court answered and the ruling. She is:','["filing a motion", "memorizing a statute number", "reading and analyzing case law", "drafting a contract"]'::jsonb,2,'Brief the facts, issue and holding.','original'),
('127.773.d.2.A',4,'The part of an opinion that states the court''s answer to the legal question is the:','["docket", "caption", "exhibit list", "holding"]'::jsonb,3,'The holding is the rule applied.','original'),
('127.773.d.2.B',3,'A researcher traces a case from the trial court through the appeals court and into a higher court review. She is analyzing the case''s:','["procedural history", "price history", "spelling history", "family history"]'::jsonb,0,'Procedural history shows how the case moved.','original'),
('127.773.d.2.B',4,'A court that reviews a lower court''s decision for legal error is acting as an:','["grand jury", "appellate court", "municipal clerk", "small claims court only"]'::jsonb,1,'Appellate courts review decisions.','original'),
('127.773.d.2.C',3,'A lawyer finds an earlier case with nearly identical facts and argues the new case should be decided the same way. She is applying:','["a sales pitch", "a weather forecast", "legal precedent", "a coin toss"]'::jsonb,2,'Precedent guides like cases.','original'),
('127.773.d.2.C',4,'The principle that courts follow earlier decisions on the same legal issue is called:','["habeas corpus", "voir dire", "nolo contendere", "stare decisis"]'::jsonb,3,'Stare decisis means to stand by decided matters.','original'),
('127.773.d.2.D',3,'A student builds an argument using a statute, two cases and a policy reason why the rule serves the public. She is developing arguments based on:','["research, relevant case law, statutes and public policy", "rumors and guesses", "personal taste only", "a random poll"]'::jsonb,0,'Good legal argument cites authority and policy.','original'),
('127.773.d.2.D',4,'Which source is the strongest support for a legal argument?','["a movie plot", "a controlling statute or binding case", "a social media comment", "a friend''s opinion"]'::jsonb,1,'Primary mandatory authority carries the most weight.','original'),
('127.773.d.3.A',3,'A new associate keeps a style manual open while editing a brief so every citation and quotation follows the same rules. She is using:','["a travel brochure", "a sports schedule", "a legal reference document such as the Bluebook", "a restaurant menu"]'::jsonb,2,'Reference manuals ensure consistency.','original'),
('127.773.d.3.A',4,'Following the Bluebook consistently helps a brief look:','["longer than needed", "funnier", "less organized", "professional and easy for a court to verify"]'::jsonb,3,'Standard citations let readers find sources.','original'),
('127.773.d.3.B',3,'A student drafts a brief with an introduction, statement of facts, argument and conclusion. She is preparing a:','["legal brief with its standard elements", "grocery list", "text thread", "travel diary"]'::jsonb,0,'Briefs follow a standard structure.','original'),
('127.773.d.3.B',4,'In a legal brief, the section that explains why the law favors the client is the:','["signature line", "argument", "table of exhibits", "caption"]'::jsonb,1,'The argument applies law to facts.','original'),
('127.773.d.3.C',3,'A junior attorney writes an internal document with a question presented, a brief answer, facts, discussion and conclusion to advise a partner. She is drafting a:','["party invitation", "press release", "legal memorandum", "menu"]'::jsonb,2,'Memos follow a set format.','original'),
('127.773.d.3.C',4,'A legal memorandum is mainly written to:','["persuade a jury with emotion", "entertain readers", "advertise a firm", "objectively analyze an issue for a colleague or client"]'::jsonb,3,'Memos are objective; briefs persuade.','original'),
('127.773.d.3.D',3,'A landlord''s attorney writes a firm letter stating the amount owed and the deadline to pay before a lawsuit is filed. This document is a:','["demand letter", "warrant", "verdict", "subpoena"]'::jsonb,0,'Demand letters request action before suit.','original'),
('127.773.d.3.D',4,'A formal written statement of a party''s claims or defenses filed with a court is called a:','["transcript", "pleading", "receipt", "menu"]'::jsonb,1,'Complaints and answers are pleadings.','original'),
('127.773.d.4.A',3,'A student maps how the U.S. Constitution outranks a state law, while common law fills in where no statute speaks. She is analyzing the:','["relationship among sports teams", "relationship among fashion brands", "relationship among constitutional, common, state and federal law", "relationship among school clubs"]'::jsonb,2,'Sources of law have a hierarchy.','original'),
('127.773.d.4.A',4,'When a state statute conflicts with the U.S. Constitution, the:','["state statute prevails", "local custom prevails", "older case prevails", "Constitution prevails"]'::jsonb,3,'The Constitution is the supreme law.','original'),
('127.773.d.4.B',3,'A class studies how a landmark ruling on school segregation changed communities and later laws. They are analyzing the legal, social and historical implications of:','["court decisions affecting society", "sports trades", "stock splits", "weather patterns"]'::jsonb,0,'Decisions have broad effects.','original'),
('127.773.d.4.B',4,'A landmark decision is important mainly because it:','["is the longest opinion", "sets a rule with lasting effects on later cases and society", "has the most footnotes", "was reported first"]'::jsonb,1,'Landmark = lasting impact.','original'),
('127.773.d.4.C',3,'After reading several rulings on police searches of phones, a student predicts how a court might rule on a new but similar case. She is:','["guessing at random", "flipping a coin", "predicting outcomes and framing arguments in light of precedent", "reading tea leaves"]'::jsonb,2,'Prediction uses precedent trends.','original'),
('127.773.d.4.C',4,'A reliable prediction of how a court will rule is based on:','["the day of the week", "the courtroom temperature", "the lawyer''s clothing", "precedent and the court''s reasoning in similar cases"]'::jsonb,3,'Precedent drives prediction.','original'),
('127.773.d.4.D',3,'A debate team reads a case on free speech in schools and writes a critique of the majority''s reasoning and the dissent''s response. They are critiquing a case on:','["U.S. constitutional law", "swim technique", "cake decorating", "gardening methods"]'::jsonb,0,'Constitutional cases can be evaluated critically.','original'),
('127.773.d.4.D',4,'A dissent in a court opinion is written by a judge who:','["did not read the case", "disagrees with the majority''s decision", "wrote the majority opinion", "was not on the court"]'::jsonb,1,'Dissenters disagree.','original'),
('127.773.d.4.E',3,'A paralegal student evaluates a recent ruling on online privacy, noting strengths and weaknesses in the court''s reasoning. She is critiquing a case on:','["an old map", "a music chart", "a current legal issue", "a historical recipe"]'::jsonb,2,'Evaluate cases on today''s issues.','original'),
('127.773.d.4.E',4,'A strong critique of a court ruling explains:','["only who attended", "only whether it was famous", "only the length of the opinion", "what the court decided and whether its reasoning is sound"]'::jsonb,3,'Critique weighs reasoning.','original'),
('127.773.d.5.A',3,'For a moot court problem on student searches, a team gathers recent cases from several courts and compares how each decided the issue. They are researching and evaluating:','["case law on a current legal issue", "menu options", "movie reviews", "travel routes"]'::jsonb,0,'Collect and compare cases.','original'),
('127.773.d.5.A',4,'When two courts reach different results on the same issue, researchers say the courts are:','["in agreement", "split in their decisions", "retired", "out of session"]'::jsonb,1,'A split signals unsettled law.','original'),
('127.773.d.5.B',3,'A moot court team reads the brief of the party who lost below, the brief of the party who won and a brief from a group not in the case that supports one side. They are reading:','["comics and cartoons", "menus and receipts", "appellant, respondent and amici briefs", "posters and flyers"]'::jsonb,2,'Amici file friend-of-the-court briefs.','original'),
('127.773.d.5.B',4,'An amicus curiae brief is filed by someone who:','["is the court reporter", "is the defendant", "is the judge", "is not a party but has an interest in the outcome"]'::jsonb,3,'Friend of the court.','original'),
('127.773.d.5.C',3,'A team writes a document asking a higher court to reverse the trial court, with a statement of the issues, facts and argument. They are writing an:','["appellate brief", "birthday card", "game schedule", "grocery list"]'::jsonb,0,'Appellate briefs argue error below.','original'),
('127.773.d.5.C',4,'An appellant''s brief argues that the lower court:','["was too slow", "made a legal error that should be corrected", "had a short docket", "used a nice courtroom"]'::jsonb,1,'Appeals claim error.','original'),
('127.773.d.5.D',3,'A student stands before three judges, presents her side in a few minutes and answers their pointed questions about the law. She is giving an:','["sales demo", "opening toast", "oral argument", "pep talk"]'::jsonb,2,'Oral argument includes questions from the bench.','original'),
('127.773.d.5.D',4,'When a judge interrupts with a question during oral argument, the best response is to:','["ignore the question", "argue with the judge", "read the brief aloud", "answer directly and tie the answer back to the law"]'::jsonb,3,'Respond to the bench directly.','original'),
('127.800.d.1.A',3,'At a county records office practicum, an intern notices the written procedure for signing out files but is in a hurry and skips it. The best choice is to:','["follow the posted policy and sign out the file", "ask a friend to sign for her", "take the file without telling anyone", "skip the policy to save time"]'::jsonb,0,'Policies protect records and people.','original'),
('127.800.d.1.A',4,'Why do public safety workplaces require staff to follow written procedures?','["they are only suggestions", "they keep work consistent, safe and legally defensible", "they make jobs longer on purpose", "they matter only to supervisors"]'::jsonb,1,'Procedures protect everyone.','original'),
('127.800.d.1.B',3,'A practicum student arrives ten minutes early each day, plans her tasks and finishes assignments before deadlines. These are examples of positive:','["clothing styles", "hobby choices", "work behaviors such as punctuality and time management", "social media habits"]'::jsonb,2,'Reliability shows professionalism.','original'),
('127.800.d.1.B',4,'Which behavior best shows a positive attitude at a placement site?','["complaining about assignments", "doing only what is asked", "arriving late but staying late", "volunteering for needed tasks and staying courteous"]'::jsonb,3,'Initiative and courtesy.','original'),
('127.800.d.1.C',3,'A supervisor tells an intern that her incident report was missing key details. The intern should:','["listen, thank the supervisor and revise the report", "avoid the supervisor afterward", "blame a coworker", "argue that the report was perfect"]'::jsonb,0,'Constructive criticism improves work.','original'),
('127.800.d.1.C',4,'Constructive criticism is most useful when it is:','["given only once a year", "specific and aimed at improving future work", "public and humiliating", "vague and personal"]'::jsonb,1,'Specific feedback improves performance.','original'),
('127.800.d.1.D',3,'A security intern finds a lost wallet with cash inside and no one around. Applying ethical reasoning, she should:','["keep the cash and turn in the wallet", "leave it where it is", "turn it in to the proper authority with the contents intact", "spend the cash on lunch"]'::jsonb,2,'Ethical decisions follow honesty and duty.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_109_v1'
from (values
('127.800.d.1.D',4,'Ethical reasoning in a public safety job means:','["following the loudest voice", "doing whatever is easiest", "protecting only friends", "weighing choices by honesty, fairness and the rules"]'::jsonb,3,'Think through right and wrong.','original'),
('127.800.d.1.E',3,'A trainee double-checks a dispatch log twice before submitting it so no address is wrong. This shows:','["completing tasks to the highest standard to ensure quality service", "rushing to finish early", "ignoring details", "avoiding responsibility"]'::jsonb,0,'Accuracy matters in public safety.','original'),
('127.800.d.1.E',4,'In emergency dispatch, a small error in an address can:','["have no effect at all", "delay help from reaching the right place", "reduce paperwork", "improve response time"]'::jsonb,1,'Quality prevents harm.','original'),
('127.800.d.1.F',3,'A job shadow in a jail teaches an intern the standards for confidentiality, use of force and respect for inmates'' rights. These are professional standards in:','["farming and ranching", "retail, fashion and sales", "law, public safety, corrections and security", "film and music"]'::jsonb,2,'Fields have professional codes.','original'),
('127.800.d.1.F',4,'A professional standard that applies to most public safety jobs is:','["posting case photos", "sharing reports online", "gossiping about cases", "keeping sensitive information confidential"]'::jsonb,3,'Confidentiality is a core standard.','original'),
('127.800.d.1.G',3,'At a fire station practicum, an intern is told to wear gloves when handling equipment and to keep walkways clear. He is learning to:','["comply with practicum safety rules and regulations", "disable alarms", "ignore posted signs", "avoid all equipment"]'::jsonb,0,'Safety rules prevent injury.','original'),
('127.800.d.1.G',4,'If an intern sees a spill in a hallway at the practicum site, the best action is to:','["pretend not to notice", "report it or clean it up according to site procedure", "wait for someone to slip", "step over it"]'::jsonb,1,'Hazards must be handled promptly.','original'),
('127.800.d.2.A',3,'A security intern notices that visitors keep forgetting to sign in at the front desk. She breaks down the causes and proposes a bright sign-in kiosk. She is:','["removing the desk", "complaining to visitors", "analyzing problem elements to develop creative solutions", "ignoring the problem"]'::jsonb,2,'Break a problem into parts, then solve.','original'),
('127.800.d.2.A',4,'The first step in creative problem solving is usually to:','["skip to implementation", "blame someone", "pick the cheapest option", "define the problem and its causes clearly"]'::jsonb,3,'Define before solving.','original'),
('127.800.d.2.B',3,'An intern receives three conflicting reports about a parking incident and checks the source, date and detail of each before deciding what to rely on. She is:','["critically analyzing information for its value", "accepting the first report", "believing the loudest report", "ignoring all reports"]'::jsonb,0,'Evaluate reliability.','original'),
('127.800.d.2.B',4,'Which question best tests whether a source of information is reliable?','["is it popular online?", "who produced it and how do they know?", "does it use big fonts?", "is it long?"]'::jsonb,1,'Check source credibility.','original'),
('127.800.d.2.C',3,'A trainee lists two ways to route patrol cars and compares speed, cost and coverage before recommending one. He is:','["copying a classmate", "flipping a coin", "comparing and contrasting alternatives using critical thinking", "guessing"]'::jsonb,2,'Weigh pros and cons.','original'),
('127.800.d.2.C',4,'A decision matrix helps a team choose by:','["avoiding data", "asking only the boss", "choosing the first idea", "scoring each option against the same criteria"]'::jsonb,3,'Consistent criteria.','original'),
('127.800.d.2.D',3,'Before recommending a new radio system, an intern reads manufacturer specifications and agency reports to gather facts. She is conducting:','["technical research to support decision making", "random browsing", "a casual chat", "party planning"]'::jsonb,0,'Decisions need technical facts.','original'),
('127.800.d.2.D',4,'Reliable technical research for a purchase decision should rely on:','["rumors", "specifications, test data and expert reports", "hunches", "advertising slogans"]'::jsonb,1,'Use evidence.','original'),
('127.800.d.3.A',3,'A sergeant earns her team''s confidence by keeping promises, admitting mistakes and staying positive in tough shifts. She is showing leadership characteristics such as:','["impatience and blame", "favoritism and gossip", "trust, positive attitude and integrity", "secrecy and pride"]'::jsonb,2,'Leaders build trust.','original'),
('127.800.d.3.A',4,'Which action most builds trust in a leader?','["changing rules randomly", "avoiding feedback", "taking credit for others'' work", "doing what she said she would do"]'::jsonb,3,'Consistency builds trust.','original'),
('127.800.d.3.B',3,'Three interns share a training scenario, each handling a different part so that the group finishes on time. They are demonstrating:','["teamwork by cooperating to achieve a goal", "avoiding the task", "working alone", "competing against each other"]'::jsonb,0,'Teams share the load.','original'),
('127.800.d.3.B',4,'Effective teamwork depends most on team members:','["working in isolation", "sharing information and supporting each other", "avoiding communication", "hiding mistakes"]'::jsonb,1,'Cooperation wins.','original'),
('127.800.d.3.C',3,'A shift group struggles to agree on a duty schedule. They list options, listen to each person and settle on a compromise everyone accepts. This demonstrates:','["letting one person decide", "walking away", "team processes such as consensus building and conflict resolution", "avoiding the problem"]'::jsonb,2,'Consensus resolves conflict.','original'),
('127.800.d.3.C',4,'Consensus building means:','["the loudest person wins", "the majority forces others", "the leader ignores input", "working until everyone can accept the decision"]'::jsonb,3,'Everyone can live with it.','original'),
('127.800.d.3.D',3,'Two interns agree to split a report. One writes her half on time while the other asks to be excused. The responsible intern shows:','["responsibility for shared group and individual work tasks", "indifference", "blame", "avoidance"]'::jsonb,0,'Meet your commitments.','original'),
('127.800.d.3.D',4,'Taking responsibility for a group task includes:','["hiding that you''re late", "finishing your part and telling the team if you need help", "waiting for someone else", "blaming the schedule"]'::jsonb,1,'Own your piece.','original'),
('127.800.d.3.E',3,'A police cadet takes time to learn her partner''s work style, shares credit for good outcomes and settles small disagreements calmly. She is:','["creating cliques", "avoiding teammates", "maintaining effective working relationships", "competing for attention"]'::jsonb,2,'Good relationships support missions.','original'),
('127.800.d.3.E',4,'A good working relationship at a public safety agency usually relies on:','["secrecy", "favoritism", "rivalry", "mutual respect and clear communication"]'::jsonb,3,'Respect and clarity.','original'),
('127.800.d.3.F',3,'A security intern greets visitors politely, listens to complaints and thanks coworkers for help. She is demonstrating effective working relationships using:','["interpersonal skills", "technical manuals", "stationery", "office furniture"]'::jsonb,0,'Interpersonal skills build relationships.','original'),
('127.800.d.3.F',4,'Which is an interpersonal skill?','["memorizing codes", "listening to understand before responding", "lifting heavy objects", "typing quickly"]'::jsonb,1,'Listening is interpersonal.','original'),
('127.800.d.3.G',3,'A corrections intern is paired with a coworker whose style differs from hers. She asks questions, adjusts her pace and offers help. She is applying:','["blame", "avoidance", "positive interpersonal skills to work cooperatively", "hostility"]'::jsonb,2,'Cooperation despite differences.','original'),
('127.800.d.3.G',4,'When a coworker does a task differently than you would, the best first step is to:','["mock their method", "report them at once", "refuse to help", "ask about their approach and look for common ground"]'::jsonb,3,'Seek understanding.','original'),
('127.800.d.3.H',3,'A deputy treats an elderly witness, a teen and a visitor from another country with the same courtesy. He is demonstrating:','["respect for individuals from different cultures, genders and backgrounds", "ignoring differences", "ranking people by age", "assuming roles by looks"]'::jsonb,0,'Respect applies to everyone.','original'),
('127.800.d.3.H',4,'Showing respect for cultural differences at work includes:','["making jokes about customs", "avoiding assumptions and learning about others'' customs", "insisting everyone act alike", "ignoring customs"]'::jsonb,1,'Learn, don''t assume.','original'),
('127.800.d.3.I',3,'A hiring panel for a security firm values employees who bring different languages, backgrounds and ideas to solve problems. This shows sensitivity to and value for:','["uniformity", "isolation", "diversity", "secrecy"]'::jsonb,2,'Diversity strengthens teams.','original'),
('127.800.d.3.I',4,'A workplace benefits from diversity mainly because:','["it lowers wages", "everyone thinks the same", "it avoids all conflict", "different viewpoints help solve problems and serve more people"]'::jsonb,3,'Variety improves solutions.','original'),
('127.800.d.4.A',3,'In a briefing, a trainee uses terms such as ''chain of custody'' and ''probable cause'' correctly when explaining a scenario. She is demonstrating:','["use of content, technical concepts and vocabulary when analyzing information", "slang for fun", "random word choice", "avoidance of detail"]'::jsonb,0,'Precise vocabulary shows understanding.','original'),
('127.800.d.4.A',4,'Using correct technical terms in a report helps the reader:','["skim faster", "understand exactly what was done", "skip steps", "guess the meaning"]'::jsonb,1,'Precision prevents confusion.','original'),
('127.800.d.4.B',3,'A dispatcher intern asks open questions to get the caller''s location, then repeats the address back to confirm. She is employing:','["silence", "gestures only", "verbal skills when obtaining and conveying information", "written notes only"]'::jsonb,2,'Clear speech and confirmation.','original'),
('127.800.d.4.B',4,'Repeating back an address to a caller is done to:','["avoid writing it", "slow the call", "impress the caller", "confirm the information is correct"]'::jsonb,3,'Read-back confirms.','original'),
('127.800.d.4.C',3,'An intern checks a state agency manual and a department database to find the correct form for a report. She is accessing:','["information sources for occupational tasks using technical materials", "entertainment websites", "social posts", "unrelated menus"]'::jsonb,0,'Use job references.','original'),
('127.800.d.4.C',4,'When you cannot remember a procedure at work, the best approach is to:','["make one up", "consult the official manual or ask a supervisor", "skip it", "guess"]'::jsonb,1,'Official sources first.','original'),
('127.800.d.4.D',3,'An intern compares a trade magazine''s claim with the agency''s published policy and notes the policy is more recent and official. She is:','["copying text", "accepting everything", "evaluating the reliability of information from technical materials", "avoiding reading"]'::jsonb,2,'Check recency and authority.','original'),
('127.800.d.4.D',4,'An official policy is generally more reliable than an unsigned online post because it:','["has more images", "has more likes", "is longer", "comes from an accountable, authoritative source"]'::jsonb,3,'Accountability matters.','original'),
('127.800.d.4.E',3,'A security trainee sees a visitor clenching fists and avoiding eye contact while saying ''I''m fine.'' She takes extra care to ask follow-up questions. She is interpreting:','["verbal and nonverbal behaviors to enhance communication", "only written text", "only spoken words", "only the weather"]'::jsonb,0,'Nonverbal cues add meaning.','original'),
('127.800.d.4.E',4,'Which nonverbal cue most likely signals discomfort?','["a calm tone", "crossed arms and avoiding eye contact", "a nod", "steady relaxed posture"]'::jsonb,1,'Body language communicates.','original'),
('127.800.d.4.F',3,'While taking a witness statement, a trainee puts down her phone, nods and asks, ''So the car turned left, correct?'' She is applying:','["finishing the sentence for the witness", "multitasking", "active listening skills to obtain and clarify information", "interrupting often"]'::jsonb,2,'Active listening clarifies.','original'),
('127.800.d.4.F',4,'Paraphrasing what a speaker said is a form of:','["arguing", "note forgery", "interrupting", "active listening"]'::jsonb,3,'Paraphrase to confirm.','original'),
('127.800.d.4.G',3,'A trainee uses grammar, spelling and clear organization to write a concise incident report that a supervisor can read quickly. She is using:','["academic skills to facilitate effective written communication", "slang", "abbreviations only", "emoji"]'::jsonb,0,'Clear writing is professional.','original'),
('127.800.d.4.G',4,'A strong incident report is:','["long and rambling", "clear, accurate and organized in a logical order", "vague and emotional", "full of opinions"]'::jsonb,1,'Reports should be factual.','original'),
('127.800.d.5.A',3,'An intern asks a supervising officer to let him practice basic report writing and radio use under supervision to build skills for his chosen career. He is developing:','["generic chat skills", "only hobby skills", "advanced technical knowledge and skills related to the occupation", "unrelated skills"]'::jsonb,2,'Practicums build job skills.','original'),
('127.800.d.5.A',4,'A supervised practicum helps a student by:','["replacing all classes", "avoiding real tasks", "eliminating the need for skills", "giving real-world practice with guidance"]'::jsonb,3,'Real practice with support.','original'),
('127.800.d.5.B',3,'After a mock traffic stop, an intern lists what went well and what slipped, such as forgetting to confirm identification. She is:','["evaluating strengths and weaknesses in technical skill proficiency", "boasting", "hiding errors", "ignoring feedback"]'::jsonb,0,'Self-assessment finds growth areas.','original'),
('127.800.d.5.B',4,'Identifying weaknesses honestly lets a trainee:','["repeat strengths only", "target practice where it''s needed most", "avoid training", "hide mistakes"]'::jsonb,1,'Target growth.','original'),
('127.800.d.5.C',3,'A supervisor points out that the intern''s evidence labels were hard to read. The intern says, ''Thank you, I''ll print them clearly next time.'' This shows she can:','["blame others", "ignore feedback", "accept critical feedback from a supervisor", "argue back"]'::jsonb,2,'Respond to feedback professionally.','original'),
('127.800.d.5.C',4,'The best response to critical feedback from a supervisor is to:','["stop asking for help", "defend every mistake", "take offense", "listen, ask clarifying questions and apply the advice"]'::jsonb,3,'Use it to improve.','original'),
('127.800.d.6.A',3,'At the end of a semester, an intern adds her certificates, a sample incident report and a supervisor''s evaluation to a folder that shows her best work. She is updating a:','["professional portfolio", "photo album", "wallet", "phone case"]'::jsonb,0,'Portfolios show work quality.','original'),
('127.800.d.6.A',4,'Which item belongs in a professional portfolio?','["a game score", "a work sample and a letter of recommendation", "a party invite", "a joke list"]'::jsonb,1,'Portfolios show evidence of skill.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_109_v1'
from (values
('127.800.d.6.B',3,'For a mock job interview, a student shares her portfolio with a panel of local officers and explains how each item shows a skill. She is:','["only reading a list", "hiding her work", "presenting the portfolio to interested stakeholders", "avoiding questions"]'::jsonb,2,'Share and explain.','original'),
('127.800.d.6.B',4,'When presenting a portfolio, it helps to:','["avoid eye contact", "read every page word for word", "skip samples", "explain what each item shows and what you learned"]'::jsonb,3,'Connect items to skills.','original'),
('127.801.d.1.A',3,'During a ride-along, a trainee describes a minor accident to a dispatcher in short, clear sentences with the street name, number of vehicles and any injuries. This is:','["clear, concise and accurate verbal communication", "silent observation", "guessing at details", "rambling description"]'::jsonb,0,'Be clear and concise.','original'),
('127.801.d.1.A',4,'In a radio report, the most useful details come first, such as:','["your lunch order", "the location and the nature of the emergency", "the weather last week", "a joke"]'::jsonb,1,'Priority information first.','original'),
('127.801.d.1.B',3,'After a mock patrol, a student organizes her notes into a short summary with times, observations and data so a supervisor can quickly follow it. She is:','["discarding data", "hiding her notes", "analyzing and effectively communicating information and observations", "only sketching"]'::jsonb,2,'Summaries make data usable.','original'),
('127.801.d.1.B',4,'Which report entry is most useful to a supervisor?','["a funny remark", "a guess about motives", "a personal opinion", "a factual note with time, place and what was observed"]'::jsonb,3,'Objective facts.','original'),
('127.801.d.1.C',3,'A trainee notices a resident''s shaky voice and tight grip on a bag while saying everything is fine. She adjusts her approach to be calmer. She is observing and interpreting:','["verbal and nonverbal cues", "only clothing brands", "only numbers", "only spelling"]'::jsonb,0,'Cues reveal feelings.','original'),
('127.801.d.1.C',4,'A calm tone and open posture can help a trainee:','["end the conversation", "reduce tension when speaking with a worried person", "increase conflict", "show dominance"]'::jsonb,1,'Calm de-escalates.','original'),
('127.801.d.1.D',3,'A trainee at a reception desk summarizes a visitor''s request back to the visitor before answering. She is:','["assuming", "ignoring", "applying active listening skills to obtain and clarify information", "interrupting"]'::jsonb,2,'Summarize to confirm.','original'),
('127.801.d.2.A',3,'During a fire drill, a trainee notices that a rear exit is blocked by a stack of boxes and independently proposes moving the boxes and adding a floor marking. She is employing:','["avoidance", "imitation", "random action", "critical-thinking skills independently and with a team"]'::jsonb,3,'Critical thinking solves problems.','original'),
('127.801.d.2.A',4,'A team facing a recurring jam at a security checkpoint should first:','["examine the process to find where the delay occurs", "shut the checkpoint", "blame the visitors", "ignore the line"]'::jsonb,0,'Find the cause.','original'),
('127.801.d.2.B',3,'A trainee breaks a long report-writing backlog into causes such as unclear forms and too few templates, then proposes a checklist. She is:','["overlooking the issue", "analyzing elements of a problem to develop creative and innovative solutions", "dropping the task", "assigning blame"]'::jsonb,1,'Analyze, then create.','original'),
('127.801.d.2.C',3,'Before choosing a vendor for evidence bags, the trainee reviews product specifications, price lists and reviews from other agencies. She is conducting:','["a social poll", "a guess", "technical research to gather information for decision making", "a coin flip"]'::jsonb,2,'Gather technical facts.','original'),
('127.801.d.3.A',3,'On the first day at a police records office, a trainee reads the safety binder and follows rules about lifting boxes, handling sharps and fire exits. He is:','["bending rules", "ignoring rules", "skipping orientation", "demonstrating an understanding of and consistently following workplace safety rules"]'::jsonb,3,'Know and follow safety rules.','original'),
('127.801.d.3.A',4,'The main purpose of workplace safety rules is to:','["prevent injury and protect people and property", "fill binders", "punish workers", "slow down work"]'::jsonb,0,'Safety first.','original'),
('127.801.d.3.B',3,'A trainee slips on a wet floor and bruises her elbow. She tells her supervisor right away and fills out the incident form. She is following:','["delay", "procedures for reporting and handling accidents and safety hazards", "secrecy", "gossip"]'::jsonb,1,'Report accidents promptly.','original'),
('127.801.d.3.B',4,'After an accident at work, the first thing a trainee should do is:','["leave quietly", "post about it online", "make sure people are safe and report it to a supervisor", "wait a week"]'::jsonb,2,'Safety and reporting.','original'),
('127.801.d.4.A',3,'A trainee arrives on time, completes each assigned task as instructed and asks what to do when finished. He is demonstrating:','["laziness", "entitlement", "avoidance", "a positive, productive work ethic"]'::jsonb,3,'Work ethic shows reliability.','original'),
('127.801.d.4.A',4,'A new corrections trainee is given a stack of filing duties on a slow afternoon. Which choice reflects a strong work ethic?','["finishing every file accurately without being reminded", "leaving the rest for the next shift", "waiting until a supervisor checks", "filing only the easy ones"]'::jsonb,0,'Reliable self-directed effort.','original'),
('127.801.d.4.B',3,'A trainee is offered a small gift by a vendor who wants a favor on a purchase. She considers the agency''s rules and fairness and politely declines. She is:','["accepting quietly", "applying ethical reasoning to make an ethical decision", "asking for more", "ignoring the offer"]'::jsonb,1,'Gifts can bias decisions.','original'),
('127.801.d.4.B',4,'Accepting a gift in exchange for a favor is a problem because it can:','["improve fairness", "build trust in the agency", "create a conflict of interest", "reduce work"]'::jsonb,2,'Conflict of interest.','original'),
('127.801.d.4.C',3,'A security trainee is tempted to skip a required badge check for a friendly visitor. She remembers that all rules apply consistently and checks the badge anyway. She is:','["ignoring laws", "skipping checks", "bending rules for friends", "complying with all applicable rules, laws and regulations in a consistent manner"]'::jsonb,3,'Rules apply equally.','original'),
('127.801.d.5.A',3,'Under supervision, a student leads a short community safety talk, writes a log of what she did and reflects on how it went. She is:','["conducting, documenting and evaluating learning activities in a supervised setting", "avoiding feedback", "acting alone without a log", "skipping documentation"]'::jsonb,0,'Do, document, evaluate.','original'),
('127.801.d.5.B',3,'An intern requests extra training on the agency''s reporting software so she can enter data faster and more accurately. She is:','["avoiding tools", "developing advanced technical knowledge and skills related to the occupation", "outsourcing the work", "skipping training"]'::jsonb,1,'Build job-specific skills.','original'),
('127.801.d.5.C',3,'A trainee keeps a glossary of job terms such as ''incident,'' ''citation'' and ''custody'' and uses them correctly in conversations with staff. He is:','["avoiding words", "using slang", "examining and articulating job-specific technical vocabulary", "guessing meanings"]'::jsonb,2,'Know the vocabulary.','original'),
('127.801.d.5.D',3,'After a practice exercise in evidence packaging, the trainee rates her accuracy and speed and notes she needs to slow down on labeling. She is:','["hiding results", "boasting", "ignoring the exercise", "evaluating strengths and weaknesses in technical skill proficiency"]'::jsonb,3,'Self-evaluation guides practice.','original'),
('127.801.d.5.E',3,'At the end of an internship, a student saves a sample report, a training certificate and a supervisor''s evaluation in a folder. She is:','["collecting representative work samples", "avoiding evidence", "tossing records", "copying others'' work"]'::jsonb,0,'Work samples show ability.','original'),
('127.801.d.1.D',4,'Which habit best shows active listening during a call or visit?','["checking your phone", "asking follow-up questions to clarify what was said", "changing the subject", "finishing the speaker''s sentences"]'::jsonb,1,'Clarifying questions show active listening.','original'),
('127.801.d.2.B',4,'After identifying causes of a problem, the next step toward a solution is to:','["ignore the findings", "pick the first idea", "brainstorm possible solutions and compare them", "cancel the project"]'::jsonb,2,'Generate options before choosing.','original'),
('127.801.d.2.C',4,'A key reason to research technical details before a purchase decision is to:','["impress coworkers", "avoid decisions", "delay the purchase", "make sure the choice meets the agency''s needs"]'::jsonb,3,'Research supports good decisions.','original'),
('127.801.d.4.C',4,'If a rule seems inconvenient but still applies, a public safety worker should:','["follow it and raise concerns through proper channels", "ignore it quietly", "change it alone", "break it once"]'::jsonb,0,'Follow rules; use channels to change them.','original'),
('127.801.d.5.A',4,'A learning log kept during a supervised practicum is useful because it:','["replaces supervision", "records activities and reflections that show growth", "hides mistakes", "avoids evaluation"]'::jsonb,1,'Logs document learning.','original'),
('127.801.d.5.B',4,'Advanced technical skills for a career are best developed through:','["skipping training", "occasional observation only", "guided practice with feedback", "avoiding hands-on tasks"]'::jsonb,2,'Practice plus feedback.','original'),
('127.801.d.5.C',4,'Why learn job-specific vocabulary in a practicum?','["it is only for tests", "it makes work longer", "it replaces skills", "it helps you communicate precisely with colleagues"]'::jsonb,3,'Vocabulary supports clear communication.','original'),
('127.801.d.5.D',4,'Honest self-evaluation of skills helps a trainee:','["focus practice on the areas that need improvement", "look more skilled", "avoid feedback", "skip practice"]'::jsonb,0,'Self-evaluation directs practice.','original'),
('127.801.d.5.E',4,'Work samples collected during a practicum are useful later because they:','["hide weaknesses", "show employers actual examples of your skills", "replace the interview", "avoid references"]'::jsonb,1,'Samples prove ability.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
